// Package pettycash is the petty cash float: deposits (top-ups from BTN Manufacturing) and expenses paid in
// cash or MTN MoMo. Only APPROVED entries move the balance. Port of legacy modules/pettycash.
package pettycash

import (
	"fmt"
	"regexp"
	"strings"
)

// Entry types / statuses / categories (Postgres enums).
const (
	TypeDeposit = "DEPOSIT"
	TypeExpense = "EXPENSE"

	StatusDraft     = "DRAFT"
	StatusSubmitted = "SUBMITTED"
	StatusApproved  = "APPROVED"
	StatusRejected  = "REJECTED"

	// PayrollSource marks entries generated by payroll: read-only here.
	PayrollSource = "PayrollPeriod"

	// AutoApprovedComment is stored in reviewComment of auto-approved entries (data, not display).
	AutoApprovedComment = "Auto-approved below limit"

	maxAmount = 500_000_000 // RWF; keeps sums far from Int overflow
)

var (
	entryTypes = []string{TypeDeposit, TypeExpense}
	categories = []string{"FLOAT_DEPOSIT", "WAGES", "SALARY", "TRANSPORT", "FUEL", "INTERNET_COMMS", "MEALS", "NIGHT_SHIFT", "MATERIALS", "MAINTENANCE", "OFFICE", "OTHER"}
	statuses   = []string{StatusDraft, StatusSubmitted, StatusApproved, StatusRejected}
)

// Line is one ledger line.
type Line struct {
	ID         string
	Type       string
	Amount     int64
	MomoCharge int64
}

// entryEffect is the signed effect of one APPROVED entry on the float: a deposit adds its amount,
// an expense removes amount plus the MoMo transfer charge.
func entryEffect(l Line) int64 {
	if l.Type == TypeDeposit {
		return l.Amount
	}
	return -(l.Amount + l.MomoCharge)
}

func netEffect(lines []Line) int64 {
	var s int64
	for _, l := range lines {
		s += entryEffect(l)
	}
	return s
}

// runningBalances returns the balance after each line (ledger order) plus the closing balance.
// The SQL window function in queries.go computes the same thing set-based; this is the reference.
func runningBalances(opening int64, lines []Line) (map[string]int64, int64) {
	out := make(map[string]int64, len(lines))
	bal := opening
	for _, l := range lines {
		bal += entryEffect(l)
		out[l.ID] = bal
	}
	return out, bal
}

type decision struct {
	Status       string
	AutoApproved bool
	ReasonKey    string
}

// approvalDecision: deposits always need GM/MD approval; expenses strictly below the limit are
// auto-approved; a limit of 0 disables auto-approval.
func approvalDecision(typ string, amount, limit int64) decision {
	if typ == TypeDeposit {
		return decision{StatusSubmitted, false, "pettycash.decision.deposit"}
	}
	if limit > 0 && amount < limit {
		return decision{StatusApproved, true, "pettycash.decision.auto"}
	}
	return decision{StatusSubmitted, false, "pettycash.decision.limit"}
}

// checkSufficientBalance: whether amount + MoMo charge can be paid from the approved balance.
func checkSufficientBalance(balance, amount, momoCharge int64) (ok bool, needed, shortfall int64) {
	needed = amount + momoCharge
	ok = needed <= balance
	if !ok {
		shortfall = needed - balance
	}
	return
}

var momoRe = regexp.MustCompile(`^(?:\+?250|0)(7\d{8})$`)
var momoStrip = regexp.MustCompile(`[\s.\-()]`)

// normaliseMomo returns the local 07XXXXXXXX form of a Rwandan mobile number, or "" when invalid.
func normaliseMomo(in string) string {
	m := momoRe.FindStringSubmatch(momoStrip.ReplaceAllString(in, ""))
	if m == nil {
		return ""
	}
	return "0" + m[1]
}

var enMonths = []string{"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}

// formatRangeLabel: "1–30 Nov 2026", "28 Oct – 3 Nov 2026", "28 Dec 2025 – 3 Jan 2026", "14 Nov 2026".
// months are the 12 month abbreviations of the output language.
func formatRangeLabel(fromISO, toISO string, months []string) string {
	var fy, fm, fd, ty, tm, td int
	fmt.Sscanf(fromISO, "%d-%d-%d", &fy, &fm, &fd)
	fmt.Sscanf(toISO, "%d-%d-%d", &ty, &tm, &td)
	if fm < 1 || fm > 12 || tm < 1 || tm > 12 {
		return fromISO + " – " + toISO
	}
	switch {
	case fromISO == toISO:
		return fmt.Sprintf("%d %s %d", fd, months[fm-1], fy)
	case fy == ty && fm == tm:
		return fmt.Sprintf("%d–%d %s %d", fd, td, months[fm-1], fy)
	case fy == ty:
		return fmt.Sprintf("%d %s – %d %s %d", fd, months[fm-1], td, months[tm-1], fy)
	}
	return fmt.Sprintf("%d %s %d – %d %s %d", fd, months[fm-1], fy, td, months[tm-1], ty)
}

// likePattern escapes %, _ and \ so user text matches literally inside ILIKE '%...%'.
func likePattern(q string) string {
	r := strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`)
	return "%" + r.Replace(q) + "%"
}
